'use client'

import { useState, useEffect } from 'react'

interface LoadingTimeoutResult {
  /** True when isLoading has been true for > 3 seconds */
  showConnectionHint: boolean
  /** True when isLoading has been true for > 10 seconds */
  showSlowHint: boolean
}

export function useLoadingTimeout(isLoading: boolean): LoadingTimeoutResult {
  const [showConnectionHint, setShowConnectionHint] = useState(false)
  const [showSlowHint, setShowSlowHint] = useState(false)

  useEffect(() => {
    if (!isLoading) {
      setShowConnectionHint(false)
      setShowSlowHint(false)
      return
    }

    const t1 = setTimeout(() => setShowConnectionHint(true), 3000)
    const t2 = setTimeout(() => setShowSlowHint(true), 10000)

    return () => {
      clearTimeout(t1)
      clearTimeout(t2)
    }
  }, [isLoading])

  return { showConnectionHint, showSlowHint }
}

'use client'

import { useState, useEffect } from 'react'
import { Loader2, Check, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SaveIndicatorProps {
  lastSavedAt?: Date | null
  status?: 'idle' | 'saving' | 'saved' | 'error'
  className?: string
}

function getRelativeTime(date: Date): string {
  const diffMs = Date.now() - date.getTime()
  const diffSec = Math.floor(diffMs / 1000)

  if (diffSec < 10) return 'just now'
  if (diffSec < 60) return `${diffSec} seconds ago`
  if (diffSec < 300) return 'a minute ago'
  return `${Math.floor(diffSec / 60)} minutes ago`
}

export function SaveIndicator({ lastSavedAt, status = 'idle', className }: SaveIndicatorProps) {
  const [, setTick] = useState(0)
  const [displayStatus, setDisplayStatus] = useState(status)

  // Sync external status changes
  useEffect(() => {
    setDisplayStatus(status)
  }, [status])

  // Auto-hide 'saved' after 5s
  useEffect(() => {
    if (displayStatus !== 'saved') return
    const t = setTimeout(() => setDisplayStatus('idle'), 5000)
    return () => clearTimeout(t)
  }, [displayStatus])

  // Re-tick every 15s so relative time stays fresh
  useEffect(() => {
    if (displayStatus !== 'saved') return
    const interval = setInterval(() => setTick((n) => n + 1), 15_000)
    return () => clearInterval(interval)
  }, [displayStatus])

  if (displayStatus === 'idle') return null

  return (
    <span className={cn('inline-flex items-center gap-1.5', className)}>
      {displayStatus === 'saving' && (
        <>
          <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" aria-hidden="true" />
          <span className="text-xs text-muted-foreground">Saving&hellip;</span>
        </>
      )}

      {displayStatus === 'saved' && (
        <>
          <Check
            className="h-3 w-3 text-[oklch(58%_0.18_145)] animate-in fade-in-0 duration-150"
            aria-hidden="true"
          />
          <span className="text-xs text-muted-foreground">
            Saved{lastSavedAt ? ` · ${getRelativeTime(lastSavedAt)}` : ''}
          </span>
        </>
      )}

      {displayStatus === 'error' && (
        <>
          <AlertCircle className="h-3 w-3 text-destructive" aria-hidden="true" />
          <span className="text-xs text-destructive">Not saved</span>
        </>
      )}
    </span>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

interface ConfirmDestructiveProps {
  /** The entity name the user must type to confirm. E.g., "Jane Doe" or "my-studio" */
  name: string
  /** The action verb used in copy. E.g., "delete", "permanently remove" */
  verb?: string
  /** Called after the user confirms (types name correctly + clicks button) */
  onConfirm: () => void | Promise<void>
  /** Controlled open state */
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Show a loading spinner on the confirm button while true */
  isLoading?: boolean
  /** Optional: context sentence added to description. E.g., "This will delete 23 appointments." */
  consequence?: string
}

const descriptionId = 'confirm-destructive-desc'

export function ConfirmDestructive({
  name,
  verb = 'Delete',
  onConfirm,
  open,
  onOpenChange,
  isLoading = false,
  consequence,
}: ConfirmDestructiveProps) {
  const [inputValue, setInputValue] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  // Reset on open
  useEffect(() => {
    if (open) {
      setInputValue('')
      // Focus input after dialog animation
      const t = setTimeout(() => inputRef.current?.focus(), 80)
      return () => clearTimeout(t)
    }
  }, [open])

  const matches = inputValue === name
  const hasTyped = inputValue.length > 0

  function handleConfirm() {
    if (!matches || isLoading) return
    void onConfirm()
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm" aria-describedby={descriptionId}>
        <DialogHeader>
          <DialogTitle>
            Permanently {verb.toLowerCase()} {name}?
          </DialogTitle>
          <DialogDescription id={descriptionId} asChild>
            <div className="space-y-1">
              <p>This action is permanent and cannot be undone.</p>
              {consequence && (
                <p className="font-medium text-foreground">{consequence}</p>
              )}
              <p className="mt-3">
                Type{' '}
                <strong className="select-none font-semibold">{name}</strong>{' '}
                to confirm.
              </p>
            </div>
          </DialogDescription>
        </DialogHeader>

        <Input
          ref={inputRef}
          placeholder={name}
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          aria-label={`Type ${name} to confirm`}
          className={cn(
            'mt-3 font-mono text-sm',
            hasTyped && !matches && 'border-destructive/50 focus-visible:ring-destructive/30',
          )}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && matches && !isLoading) handleConfirm()
          }}
        />

        <DialogFooter className="mt-4">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
          >
            Cancel
          </Button>
          <Button
            variant="destructive"
            disabled={!matches || isLoading}
            aria-disabled={!matches || isLoading}
            onClick={handleConfirm}
          >
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {verb} {name}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useEffect } from 'react'
import Link from 'next/link'
import { AlertTriangle } from 'lucide-react'
import { logger } from '@/lib/logger'
import { Button } from '@/components/ui/button'
import { Typography } from '@/components/ui/typography'

type PageErrorVariant = 'full-page' | 'inline' | 'customer'

interface PageErrorProps {
  error: Error & { digest?: string }
  reset: () => void
  /** Route name for logging context */
  routeContext?: string
  /**
   * full-page (default) — min-h 60vh, shows digest, "Go to dashboard" link. Technical tone.
   * inline              — no min-h, no digest, no nav links. Compact retry-focused.
   * customer            — min-h 60vh, no digest, "Go home" links to /. Friendly tone.
   */
  variant?: PageErrorVariant
}

export function PageError({ error, reset, routeContext, variant = 'full-page' }: PageErrorProps) {
  useEffect(() => {
    logger.error('PageError boundary triggered', {
      error: error.message,
      digest: error.digest,
      routeContext,
      variant,
    })
  }, [error, routeContext, variant])

  const isFullPage = variant === 'full-page'
  const isCustomer = variant === 'customer'
  const isInline = variant === 'inline'

  const heading = isCustomer ? 'Something went wrong' : 'Something went wrong'
  const body = isCustomer
    ? 'We hit a snag. Please try again — if this keeps happening, contact support.'
    : isInline
    ? 'Failed to load this section. Retry or refresh the page.'
    : 'An unexpected error occurred. Our team has been notified.'

  return (
    <div
      className={[
        'flex flex-col items-center justify-center gap-4 p-8 text-center',
        isInline ? '' : 'min-h-[60vh]',
        isInline ? 'py-8' : '',
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {/* Icon */}
      <div className="flex size-16 items-center justify-center rounded-2xl bg-destructive/8 mb-2">
        <AlertTriangle className="size-8 text-destructive/60" aria-hidden="true" />
      </div>

      {/* Heading */}
      <Typography variant={isInline ? 'h3' : 'h2'}>{heading}</Typography>

      {/* Description */}
      <Typography variant="body" className="text-muted-foreground max-w-sm">
        {body}
      </Typography>

      {/* Error ID — only on full-page technical variant */}
      {isFullPage && error.digest && (
        <Typography variant="caption" className="font-mono">
          Error ID: {error.digest}
        </Typography>
      )}

      {/* Actions */}
      <div className="flex flex-wrap items-center justify-center gap-3 mt-2">
        <Button onClick={reset}>Try again</Button>

        {isFullPage && (
          <Button variant="outline" render={<Link href="/dashboard" />}>
            Go to dashboard
          </Button>
        )}

        {isCustomer && (
          <>
            <Button variant="outline" render={<Link href="/" />}>
              Go home
            </Button>
            <Button variant="outline" render={<a href="mailto:support@inkos.io" />}>
              Contact support
            </Button>
          </>
        )}
      </div>
    </div>
  )
}

import type { LucideIcon } from 'lucide-react'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'

type EmptyStateVariant =
  | 'default'
  | 'filtered'
  | 'first-time'
  | 'no-results'
  | 'error'
  | 'coming-soon'
  | 'permission'

interface EmptyStateCta {
  label: string
  onClick?: () => void
  href?: string
}

interface EmptyStateProps {
  icon: LucideIcon
  title: string
  description?: string
  cta?: EmptyStateCta
  ctaSecondary?: EmptyStateCta
  variant?: EmptyStateVariant
  size?: 'sm' | 'md' | 'lg'
  className?: string
}

function CtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" render={<Link href={cta.href} />}>
        {cta.label}
      </Button>
    )
  }
  return (
    <Button size="sm" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

function SecondaryCtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" variant="outline" render={<Link href={cta.href} />}>
        {cta.label}
      </Button>
    )
  }
  return (
    <Button size="sm" variant="outline" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

export function EmptyState({
  icon: Icon,
  title,
  description,
  cta,
  ctaSecondary,
  variant = 'default',
  size = 'md',
  className,
}: EmptyStateProps) {
  const iconSizeMap = {
    sm: 'h-5 w-5',
    md: 'h-7 w-7',
    lg: 'h-9 w-9',
  }
  const wrapSizeMap = {
    sm: 'h-10 w-10 rounded-xl',
    md: 'h-14 w-14 rounded-2xl',
    lg: 'h-16 w-16 rounded-2xl',
  }
  const pyMap = {
    sm: 'py-8',
    md: 'py-16',
    lg: 'py-20',
  }

  // Per-variant container wrapper classes
  const containerClass: Partial<Record<EmptyStateVariant, string>> = {
    'first-time': 'bg-primary/[0.02] rounded-2xl p-8',
    'coming-soon': 'relative',
  }

  // Per-variant icon wrapper classes (only 'error' deviates from primary palette)
  const iconWrapClass: Partial<Record<EmptyStateVariant, string>> = {
    error: 'border-destructive/15 bg-destructive/8',
  }

  // Per-variant icon color
  const iconColorClass: Partial<Record<EmptyStateVariant, string>> = {
    error: 'text-destructive/70',
    permission: 'text-muted-foreground/60',
  }

  // Glow always visible for first-time regardless of size
  const showGlow = size !== 'sm' || variant === 'first-time'

  const isError = variant === 'error'
  const defaultIconWrap = 'border border-primary/15 bg-primary/8 shadow-[var(--shadow-soft)]'
  const resolvedIconWrap = iconWrapClass[variant] ?? defaultIconWrap
  const resolvedIconColor = iconColorClass[variant] ?? 'text-primary/80'

  return (
    <div className={cn('max-w-[480px] mx-auto', containerClass[variant], className)}>
      {/* coming-soon gradient gradient above */}
      {variant === 'coming-soon' && (
        <div
          className="absolute -top-12 left-0 right-0 h-12 bg-gradient-to-b from-primary/[0.03] to-transparent pointer-events-none"
          aria-hidden="true"
        />
      )}

      <div
        className={cn(
          'flex flex-col items-center justify-center text-center',
          pyMap[size],
          (variant === 'filtered' || variant === 'no-results') && 'opacity-80',
        )}
      >
        <div className="relative mb-4 flex items-center justify-center">
          {showGlow && (
            <div
              className={cn(
                'absolute h-16 w-16 rounded-full blur-xl',
                isError ? 'bg-destructive/6' : 'bg-primary/6',
              )}
              aria-hidden="true"
            />
          )}
          <div
            className={cn(
              'relative flex items-center justify-center',
              wrapSizeMap[size],
              resolvedIconWrap,
              // Add border for error variant
              isError ? '' : '',
            )}
          >
            <Icon
              className={cn(iconSizeMap[size], resolvedIconColor)}
              aria-hidden="true"
            />
          </div>
        </div>

        <p className="mb-1 text-base font-semibold">{title}</p>

        {description && (
          <p
            className={cn(
              'max-w-[300px] text-sm text-muted-foreground',
              (cta ?? ctaSecondary) ? 'mb-6' : '',
            )}
          >
            {description}
          </p>
        )}

        {(cta ?? ctaSecondary) && (
          <div className="flex flex-wrap items-center justify-center gap-2">
            {cta && <CtaButton cta={cta} />}
            {ctaSecondary && <SecondaryCtaButton cta={ctaSecondary} />}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import type { ReactNode } from 'react'
import { Inbox, Loader2 } from 'lucide-react'
import { EmptyState } from './EmptyState'
import { PageError } from './PageError'
import { useLoadingTimeout } from '@/lib/hooks/use-loading-timeout'

interface DataStateProps<T> {
  /** The resolved data. Pass undefined/null while loading. */
  data: T | null | undefined
  /** True while the fetch/query is in-flight. */
  isLoading?: boolean
  /** True if the fetch/query threw or returned an error. */
  isError?: boolean
  /** The error object (used by inline error slot). */
  error?: Error | null
  /**
   * Override empty detection. If omitted:
   * - Array data: isEmpty = data.length === 0
   * - Non-array data: isEmpty = data == null
   */
  isEmpty?: boolean
  /**
   * Render the success state. Called only when not loading, not error, not empty.
   * Receives the resolved (non-null) data.
   */
  children: (data: NonNullable<T>) => ReactNode
  /** Custom loading slot. Default: centered Loader2 spinner. */
  loadingSlot?: ReactNode
  /** Custom empty slot. Default: <EmptyState title="Nothing here yet" icon={Inbox} /> */
  emptySlot?: ReactNode
  /** Custom error slot. Default: inline <PageError variant="inline" /> */
  errorSlot?: ReactNode
}

function computeIsEmpty<T>(data: T | null | undefined, override?: boolean): boolean {
  if (override !== undefined) return override
  if (data == null) return true
  if (Array.isArray(data)) return data.length === 0
  return false
}

// eslint-disable-next-line @typescript-eslint/no-unnecessary-type-constraint
export function DataState<T extends unknown>({
  data,
  isLoading = false,
  isError = false,
  error,
  isEmpty: isEmptyOverride,
  children,
  loadingSlot,
  emptySlot,
  errorSlot,
}: DataStateProps<T>) {
  const { showConnectionHint, showSlowHint } = useLoadingTimeout(isLoading)

  // State resolution: error → loading → empty → children(data)
  if (isError) {
    return (
      <>
        {errorSlot ?? (
          <PageError
            error={error ?? new Error('An error occurred')}
            reset={() => undefined}
            variant="inline"
          />
        )}
      </>
    )
  }

  if (isLoading) {
    const defaultSpinner = (
      <div
        className="flex flex-col items-center justify-center py-12"
        aria-busy="true"
        aria-label="Loading"
      >
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
        {/* Timeout hints only show when using default spinner, not custom skeleton */}
        {showConnectionHint && !showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            Still loading — check your connection?
          </p>
        )}
        {showSlowHint && (
          <p className="mt-3 text-center text-xs text-muted-foreground">
            This is taking longer than expected.{' '}
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="underline underline-offset-2 hover:text-foreground transition-colors"
            >
              Retry
            </button>
          </p>
        )}
      </div>
    )

    return <>{loadingSlot ?? defaultSpinner}</>
  }

  const isEmpty = computeIsEmpty(data, isEmptyOverride)

  if (isEmpty) {
    return (
      <>
        {emptySlot ?? (
          <EmptyState
            icon={Inbox}
            title="Nothing here yet"
            size="md"
            variant="default"
          />
        )}
      </>
    )
  }

  // data is non-null at this point: TypeScript can't know but we enforce via isEmpty check
  return <>{children(data as NonNullable<T>)}</>
}

