'use client'

import { useState, useEffect } from 'react'
import { Loader2, Check, AlertCircle } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SaveIndicatorProps {
  lastSavedAt?: Date | null
  status?: 'idle' | 'saving' | 'saved' | 'error'
  className?: string
}

function getRelativeTime(date: Date): string {
  const diffMs = Date.now() - date.getTime()
  const diffSec = Math.floor(diffMs / 1000)
  if (diffSec < 10) return 'just now'
  if (diffSec < 60) return `${diffSec} seconds ago`
  if (diffSec < 300) return 'a minute ago'
  return `${Math.floor(diffSec / 60)} minutes ago`
}

export function SaveIndicator({ lastSavedAt, status = 'idle', className }: SaveIndicatorProps) {
  const [, setTick] = useState(0)
  const [displayStatus, setDisplayStatus] = useState(status)

  useEffect(() => {
    setDisplayStatus(status)
  }, [status])

  useEffect(() => {
    if (displayStatus !== 'saved') return
    const t = setTimeout(() => setDisplayStatus('idle'), 5000)
    return () => clearTimeout(t)
  }, [displayStatus])

  useEffect(() => {
    if (displayStatus !== 'saved') return
    const interval = setInterval(() => setTick((n) => n + 1), 15_000)
    return () => clearInterval(interval)
  }, [displayStatus])

  if (displayStatus === 'idle') return null

  return (
    <span className={cn('inline-flex items-center gap-1.5', className)}>
      {displayStatus === 'saving' && (
        <>
          <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" aria-hidden="true" />
          <span className="text-xs text-muted-foreground">Saving&hellip;</span>
        </>
      )}

      {displayStatus === 'saved' && (
        <>
          <Check
            className="h-3 w-3 text-[oklch(58%_0.18_145)] animate-in fade-in-0 duration-150"
            aria-hidden="true"
          />
          <span className="text-xs text-muted-foreground">
            Saved{lastSavedAt ? ` · ${getRelativeTime(lastSavedAt)}` : ''}
          </span>
        </>
      )}

      {displayStatus === 'error' && (
        <>
          <AlertCircle className="h-3 w-3 text-destructive" aria-hidden="true" />
          <span className="text-xs text-destructive">Not saved</span>
        </>
      )}
    </span>
  )
}
