          </DataState>
        </TabsContent>

        <TabsContent value="invites" className="mt-0 p-6">
          <DataState
            data={invites}
            isLoading={loading}
            isError={!!fetchError}
            error={fetchError}
            loadingSlot={<ListSkeleton rows={2} />}
