function StatesSection() {
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle')
  const [dataStateDemo, setDataStateDemo] = useState<'loading' | 'error' | 'empty' | 'data'>('data')

  function simulateSave(outcome: 'saved' | 'error') {
    setSaveStatus('saving')
    setTimeout(() => setSaveStatus(outcome), 1200)
  }

  const demoData = dataStateDemo === 'data' ? [{ id: '1', name: 'Sample item' }] : undefined
  const demoIsLoading = dataStateDemo === 'loading'
  const demoIsError = dataStateDemo === 'error'
  const demoIsEmpty = dataStateDemo === 'empty'

  return (
    <div className="space-y-10">
      {/* EmptyState variants */}
      <div>
        <Typography variant="h3" className="mb-4">EmptyState Variants</Typography>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {(['default', 'first-time', 'no-results', 'filtered', 'error', 'coming-soon', 'permission'] as const).map((variant) => (
            <div key={variant} className="rounded-xl border border-border/50 overflow-hidden">
              <div className="bg-muted/30 px-3 py-1.5 border-b border-border/50">
                <span className="text-[11px] font-mono text-muted-foreground">{variant}</span>
              </div>
              <EmptyState
                icon={Package}
                title={variant === 'error' ? 'Failed to load data' : variant === 'permission' ? 'Access denied' : `No items — ${variant}`}
                description={variant === 'error' ? 'Something went wrong. Try again.' : variant === 'permission' ? 'You need owner access to view this.' : 'Try adjusting your filters or adding new items.'}
                variant={variant}
                size="sm"
              />
            </div>
          ))}
        </div>
      </div>

