          <div className="flex flex-wrap gap-2">
            {(['loading', 'error', 'empty', 'data'] as const).map((s) => (
              <Button
                key={s}
                size="sm"
                variant={dataStateDemo === s ? 'default' : 'outline'}
                onClick={() => setDataStateDemo(s)}
              >
                {s}
              </Button>
            ))}
          </div>
          <div className="rounded-xl border border-border/50 min-h-32 p-2">
            <DataState
              data={demoIsEmpty ? [] : demoData}
              isLoading={demoIsLoading}
              isError={demoIsError}
              error={demoIsError ? new Error('Demo error — network timeout') : null}
