          </div>
        </div>
      </div>

      {/* PageError variants */}
      <div>
        <Typography variant="h3" className="mb-4">PageError Variants</Typography>
        <div className="grid gap-4 sm:grid-cols-2">
          {(['inline', 'customer'] as const).map((variant) => (
