'use client'

import { useState, useEffect, useRef } from 'react'
import { Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

interface ConfirmDestructiveProps {
  name: string
  verb?: string
  onConfirm: () => void | Promise<void>
  open: boolean
  onOpenChange: (open: boolean) => void
  isLoading?: boolean
  consequence?: string
}

const DESCRIPTION_ID = 'confirm-destructive-desc'

export function ConfirmDestructive({
  name,
  verb = 'Delete',
  onConfirm,
  open,
  onOpenChange,
  isLoading = false,
  consequence,
}: ConfirmDestructiveProps) {
  const [inputValue, setInputValue] = useState('')
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (open) {
      setInputValue('')
      const t = setTimeout(() => inputRef.current?.focus(), 80)
      return () => clearTimeout(t)
    }
  }, [open])

  const matches = inputValue === name
  const hasTyped = inputValue.length > 0

  function handleConfirm() {
    if (!matches || isLoading) return
    void onConfirm()
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm" aria-describedby={DESCRIPTION_ID}>
        <DialogHeader>
          <DialogTitle>
            Permanently {verb.toLowerCase()} {name}?
          </DialogTitle>
          <DialogDescription id={DESCRIPTION_ID} asChild>
            <div className="space-y-1">
              <p>This action is permanent and cannot be undone.</p>
              {consequence && (
                <p className="font-medium text-foreground">{consequence}</p>
              )}
              <p className="mt-3">
                Type{' '}
                <strong className="select-none font-semibold">{name}</strong>{' '}
                to confirm.
              </p>
            </div>
          </DialogDescription>
        </DialogHeader>

        <Input
          ref={inputRef}
          placeholder={name}
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          aria-label={`Type ${name} to confirm`}
          className={cn(
            'mt-3 font-mono text-sm',
            hasTyped && !matches && 'border-destructive/50 focus-visible:ring-destructive/30',
          )}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && matches && !isLoading) handleConfirm()
          }}
        />

        <DialogFooter className="mt-4">
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isLoading}
          >
            Cancel
          </Button>
          <Button
            variant="destructive"
            disabled={!matches || isLoading}
            aria-disabled={!matches || isLoading}
            onClick={handleConfirm}
          >
            {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {verb} {name}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

import { Skeleton } from '@/components/ui/skeleton'

